// C
int input;
int sum = 0;
printf("enter numbers(0: quit): \n");
while (true) {
  scanf("%d", &input);
  if (input == 0) break;
  sum += input;
}
printf("sum: %d\n", sum);
return 0;

; Pep/8 (원문 배치)
BR main
input: .BLOCK 2
sum: .BLOCK 2
msg1: .ASCII "enter numbers(0: quit): \x00"
msg2: .ASCII "sum: \x00"
main: STRO msg1,d
while: DECI input,d
① __________
CPA 0,i
② __________
ADDA sum,d
STA sum,d
③ __________
endWhile: STRO msg2,d
DECO sum,d
STOP
.END
